export const ETATS=[['preconsult','Préconsult.','#ececea'],['devis','Devis','#fff4d6'],['perdu','Perdu','#fdeae7'],['a_debuter','À débuter','#e8f0fb'],['en_cours','En cours','#e6f5ec'],['termine','Terminé','#efeafb']];
