/* 14/10 nuit (sécurité — le site est public) : les paramètres SCR de l'ancien tableau V2B (taux horaire, équipes, cadences, marge, RCFA par client, prix radio)
   ne sont PLUS dans le code. Ils viennent du registre « prix », ligne « v1 » (lecture réservée encadrement / bureau / administrateur), remplie par le pack SCR
   (partie « chiffrageV1 »). Sans elle : valeurs de DÉMONSTRATION (fictives) et un bandeau le dit. Restent ici : pouces, kg/ml, m³/ml (données physiques). */
const DEMO_V1={demo:true,taux:60,heures:10,nSoud:3,nManch:1,autocontrole:0.05,ratioManchons:0.8,marge:0.1,dechets:0.1,radioPct:0.05,radioVac:10,radioForfait:1500,radioPU:[[65,80],[200,100],[400,110],[9999,130]],
  cad:{20:[15,15],25:[15,15],32:[15,15],40:[15,15],50:[15,15],65:[12,12],80:[12,12],100:[10,10],125:[10,10],150:[8,8],200:[8,8],250:[6,6],300:[5,5],350:[4,4],400:[4,4],450:[3,3],500:[3,3],600:[2,2]},rcfa:{}};
export function v1Params(){const r=regGet('prix','v1');return r&&+r.taux>0?Object.assign({},DEMO_V1,r,{demo:false}):DEMO_V1;}
export const v1Demo=()=>!!v1Params().demo;
const V1_KEYS=['taux','heures','nSoud','nManch','autocontrole','ratioManchons','marge','dechets','radioPct','radioVac','radioForfait'];
export const v1Base=()=>{const P=v1Params();const o={};V1_KEYS.forEach(k=>{o[k]=+P[k];});return o;};
export const rcfaOf=client=>{const c=String(client||'').toUpperCase();const R=v1Params().rcfa||{};for(const k in R)if(k&&c.includes(String(k).toUpperCase()))return +R[k]||0;const b2=prixBase();if(b2){try{const v=rcfaOfBase(b2,client);if(v!==null&&v!==undefined)return v;}catch(e){}}return 0;};
// DN : [pouces, kg/ml acier, m³/ml (iso 2)] — les cadences (soudure 3 pers / j, manchon 1 pers / j) viennent de v1Params().cad
const DN_PHYS={20:[1,6.3,0.0094985],25:[1,6.3,0.0094985],32:[1.25,6.3,0.012265625],40:[1.5,6.3,0.012265625],50:[2,6.3,0.015386],65:[2.5,7.9,0.020096],80:[3,9.9,0.025434],100:[4,14.6,0.039740625],125:[5,17.7,0.0490625],150:[6,23,0.061544],200:[8,34.6,0.098929625],250:[10,50.4,0.1589625],300:[12,64.5,0.19625],350:[14,74.6,0.246176],400:[16,94.9,0.3115665],450:[18,109.8,0.3115665],500:[20,125,0.39571850],600:[24,150,0.39571850]};
export const DNS=Object.keys(DN_PHYS).map(Number);
const dnRow=(dn,P)=>{const f=DN_PHYS[dn];if(!f)return null;const c=(P.cad||{})[dn]||DEMO_V1.cad[dn]||[0,0];return [f[0],+c[0]||0,+c[1]||0,f[1],f[2]];};
const radioPU=(dn,P)=>{const B=(P||v1Params()).radioPU||DEMO_V1.radioPU;const x=B.find(b=>dn<=+b[0]);return x?+x[1]:0;};
/* pack SCR, partie « chiffrageV1 » : {taux, heures, nSoud, nManch, autocontrole, ratioManchons, marge, dechets, radioPct, radioVac, radioForfait, radioPU:[[dnMax,€]…], cad:{dn:[soudure,manchon]}, rcfa:{CLIENT:taux}} */
export const v1Pack={key:'chiffrageV1',label:'Chiffrage : paramètres de l\'ancien tableau V2B (taux, cadences, RCFA, radios)',import:async part=>{if(!part||!(+part.taux>0))throw new Error('partie chiffrageV1 invalide (taux manquant)');const o={};V1_KEYS.forEach(k=>{if(part[k]!==undefined)o[k]=+part[k];});o.radioPU=Array.isArray(part.radioPU)?part.radioPU.map(x=>[+x[0],+x[1]]):DEMO_V1.radioPU;o.cad=part.cad||{};o.rcfa=part.rcfa||{};o.at=new Date().toISOString();o.by=A&&A.userName?A.userName():'';regSet('prix','v1',o,{replace:true});return 'paramètres V2B : taux '+o.taux+' €/h, '+Object.keys(o.cad).length+' cadences, '+Object.keys(o.rcfa).length+' clients RCFA';}};
export const v1DemoBanner=()=>v1Demo()?`<div class="warnbox" style="margin:6px 0">⚠ Paramètres de l'ancien tableau de chiffrage : <b>valeurs de démonstration</b> (fictives). Les vrais (taux horaire, cadences, RCFA, radios) arrivent avec le pack SCR — Entreprise → Outils → Pack SCR.</div>`:'';
export const CHAPITRES=[['amene','Amené – repli – nettoyage'],['conteneur','Conteneur – benne – pelle (rotation, déchets)'],['decharg','Déchargement'],['bardage','Bardage'],['purges','Purges'],['vidanges','Vidanges'],['vannes','Vannes préisolées'],['sst','Vannes SST'],['raccord','Raccordement sur existant'],['ressuage','Ressuage externe'],['us','Contrôles ultrasons'],['radio','Radio (vacations supplémentaires)'],['epreuve','Épreuve hydraulique'],['eau','Eau adoucie'],['boulet','Boulet mousse'],['rincage','Rinçage'],['passivation','Passivation'],['fo_preiso','Fournitures pré-isolées'],['fo_acier','Fournitures acier nu'],['fo_autres','Fournitures autres'],['calo','Calorifuge + peinture + supports'],['aerien','Pose aérien'],['foncage','Fonçage'],['depose','Dépose réseau'],['extrusion','Extrusion'],['etiquettes','Étiquettes'],['nuit','Plus-value nuit'],['doe','DOE / plans iso'],['etudes','Études diverses'],['autre','Autres prestations']];
/* ── calcul d'une zone (lot) : lignes par DN {dn, nb (soudures), ml (tranchée)} ── */
export function calcZone(z,base){const P=v1Params();base=Object.assign({},v1Base(),base||{});const out={rows:[],soud:0,manch:0,auto:0,pouces:0,nb:0,ml:0,jS:0,jM:0,t:0,m3:0,radios:0,radioEur:0};
  const cS=base.taux*base.heures*base.nSoud,cM=base.taux*base.heures*base.nManch;
  (z.rows||[]).forEach(r=>{const dn=+r.dn;const b=dnRow(dn,P);if(!b)return;const nbS=+r.nb||0,ml=+r.ml||0;const [pouce,cadS,cadM,kg,m3]=b;const pPouce=cadS&&pouce?cS/(cadS*pouce):0,pManch=cadM?cM/cadM:0;const pouces=nbS*pouce;const soud=pouces*pPouce;const manch=nbS*pManch*base.ratioManchons;const auto=soud*base.autocontrole;const jS=cadS?nbS/cadS:0,jM=cadM?nbS/cadM:0;const radios=nbS*base.radioPct;
    out.rows.push({dn,nb:nbS,ml,pouce,pouces,pPouce,pManch,soud,manch,auto,jS,jM,t:base.dechets*ml*kg/1000,m3:base.dechets*ml*m3,radios,radioEur:radios*radioPU(dn,P)});
    out.nb+=nbS;out.ml+=ml;out.pouces+=pouces;out.soud+=soud;out.manch+=manch;out.auto+=auto;out.jS+=jS;out.jM+=jM;out.t+=base.dechets*ml*kg/1000;out.m3+=base.dechets*ml*m3;out.radios+=radios;out.radioEur+=radios*radioPU(dn,P);});
  out.radioVacs=out.radios?Math.ceil(out.radios/base.radioVac):0;out.radioEur+=out.radioVacs*base.radioForfait;out.achat=out.soud+out.manch+out.auto+out.radioEur;return out;}
/* 12/10 (Ethan) : le chargé d'affaires se choisit dans une liste — chargés d'affaires, responsable commercial, directeur technique, responsable d'exploitation, gérant,
   responsable des opérations, conducteurs ; le conducteur parmi l'encadrement travaux. La valeur reste un nom (compatible avec les initiales importées du reporting). */
export const CHARGE_POSTES=['charge_affaires','resp_commercial','dir_technique','resp_exploitation','gerant','resp_operations','conducteur'];
export const CDTX_POSTES=['conducteur','resp_exploitation','resp_operations','chef'];
function peopleOpts(ctx,postes,cur){const P=((ctx&&ctx.people)||[]).filter(p=>p&&postes.includes(p.poste)).map(p=>p.name||((p.prenom||'')+' '+(p.nom||'')).trim()).filter(Boolean);if(!P.length)return null; /* personne de ces postes (démo, hors connexion) : saisie libre */const L=[...new Set(P)].sort((a,b)=>a.localeCompare(b,'fr'));if(cur&&!L.includes(cur))L.unshift(cur);
  return `<option value="">—</option>${L.map(n=>`<option value="${esc(n)}"${n===cur?' selected':''}>${esc(n)}</option>`).join('')}`;}
export function calcAffaire(a){const ch=a.chiffrage||{};const b2=prixBase();if(b2&&Array.isArray(ch.etudes)&&ch.etudes.length)return calcAffaireV2(a,b2); /* 13/10 : moteur v2 (zones, paniers, base de prix) dès qu'une zone existe et que la base est importée ; sinon l'ancien tableau V2B */
  const base=Object.assign({},v1Base(),ch.base||{});const zones=(ch.zones||[]).map(z=>Object.assign({nom:z.nom},calcZone(z,base)));const chap=(ch.chapitres||[]).reduce((s,c)=>s+(+c.achat||0),0);
  const achat=zones.reduce((s,z)=>s+z.achat,0)+chap;const vente=base.marge<1?achat/(1-base.marge):achat;const rcfaPct=ch.rcfa!==undefined&&ch.rcfa!==null&&ch.rcfa!==''?+ch.rcfa:rcfaOf(a.client);const rcfa=vente*rcfaPct;const total=vente+rcfa;const ml=zones.reduce((s,z)=>s+z.ml,0);
  return {zones,chap,achat,vente,rcfaPct,rcfa,total,ml,parMl:ml?total/ml:0,marge:base.marge,nb:zones.reduce((s,z)=>s+z.nb,0),jS:zones.reduce((s,z)=>s+z.jS,0),jM:zones.reduce((s,z)=>s+z.jM,0),t:zones.reduce((s,z)=>s+z.t,0),m3:zones.reduce((s,z)=>s+z.m3,0)};}
/* ── facturation ── */
export const FACT_ETAPES=[['envoi','Envoi situation'],['valid_sit','Validation situation'],['prep','Préparation facture'],['valid_fac','Validation facture'],['drive','Enregistrement Drive'],['depot','Dépôt de facture'],['avoir','Avoir'],['paye','Payée']];
export function factTotaux(a,year){const f=a.fact||{};const y=year||new Date().getFullYear();const mois=MOIS.map((m,i)=>+f[y+'-'+String(i+1).padStart(2,'0')]||0);const annee=mois.reduce((s,x)=>s+x,0);const avant=Object.keys(f).filter(k=>k<y+'-01').reduce((s,k)=>s+(+f[k]||0),0)+(+a.cumulN1||0);const cumul=avant+annee;const restant=(+a.montant||0)-cumul;return {mois,annee,avant,cumul,restant,y};}
/* ── données ── */
export const affLoad=()=>regLoad(['affaire','prix','panier']); /* 13/10 : + base de prix et paniers libres (chiffrage v2) */
export const affAll=()=>regAll('affaire').filter(a=>a&&a.num).sort((a,b)=>String(b.num).localeCompare(String(a.num)));
/* 14/10 après-midi (lot D) : CONSULTATION d'une version figée — pendant le rendu (et les actions) d'un onglet consulté, affGet(n° de l'affaire) rend l'affaire
   VIRTUELLE de la version (son instantané) et toute écriture sur cette affaire est refusée : les renderers des autres lots servent tels quels, en lecture seule. */
let VOVER=null;
export function affWithVirtual(va,fn){const prev=VOVER;VOVER=va?{num:va.num,a:va}:null;try{return fn();}finally{VOVER=prev;}}
const roRefuse=()=>{if(A&&A.toast)A.toast('Lecture seule : tu consultes une version figée — « Revenir à la version en cours » pour modifier');};
export const affGet=id=>VOVER&&id===VOVER.num?VOVER.a:regGet('affaire',id);
export function affOpen(num,tab){AS.view='fiche';AS.cur=num;AS.tab=tab||'fiche';AS.zone=0;AS.vview=null;} /* 14/10 : retour du traceur (index.html?aff=…) → l'affaire s'ouvre directement, onglet demandé (Tracé & chantiers) */
export function affSet(id,patch){if(VOVER&&id===VOVER.num){roRefuse();return VOVER.a;}return regSet('affaire',id,patch);}
export function affSetQuiet(id,patch){if(VOVER&&id===VOVER.num){roRefuse();return VOVER.a;}return regSet('affaire',id,patch,{quiet:true});} /* 13/10 : sans redessiner (frappe dans le mémoire) */
export function affNew(num,data){return regSet('affaire',num,Object.assign({num,etat:'preconsult',at:new Date().toISOString(),by:A.userName?A.userName():''},data||{}));}
/* 19/10 (lot QF, Ethan : « enlève les notifs qui touchent aux offres sur les dossiers importés : ce sont de vieux historiques ; garde le principe pour les nouveaux dossiers »).
   Affaire IMPORTÉE du reporting (SQL du 10/10) : by === 'import' ou source « Reporting … » → aucune alerte ni notification d'offre (À faire, pastilles, tuiles de la fiche).
   Elle reste visible et modifiable. Elle REDEVIENT SUIVIE (règle simple) dès que quelqu'un a saisi dans l'appli une date de réponse (dateReponseBy, posé par l'onglet Dossier)
   ET fait une étape de l'offre : une tâche du dossier cochée, une version de chiffrage, une pièce de l'offre cochée ou l'offre remise. */
export const affSuivieApp=a=>!!(a&&a.dateReponseBy&&(Object.values(a.taches||{}).some(Boolean)||(Array.isArray(a.chiffrages)&&a.chiffrages.length>0)||(+a.chiffrageV||1)>1||Object.values((a.offre||{}).pieces||{}).some(Boolean)||!!(a.offre&&a.offre.remiseAt)));
export const affEstImportee=a=>!!a&&(a.by==='import'||/^Reporting/i.test(String(a.source||'')))&&!affSuivieApp(a);
export const SECT_LETTER={O:'ouest',I:'idf',S:'sud',W:'sudouest',E:'est'};
export const parentNum=num=>{const m=String(num||'').match(/^([A-Z]\d{4}-\d{2})/);return m?m[1]:String(num||'');};
export const isSub=a=>parentNum(a.num)!==String(a.num);
