export function affNextNum(secteur,d){const now=d||new Date();const L={ouest:'O',idf:'I',sud:'S',sudouest:'W',sudest:'S',est:'E'}[secteur||'ouest']||'O';const pre=L+String(now.getFullYear()).slice(2)+String(now.getMonth()+1).padStart(2,'0')+'-';const ranks=affAll().map(a=>String(a.num)).filter(n=>n.startsWith(pre)).map(n=>parseInt(n.slice(pre.length),10)).filter(n=>isFinite(n));return pre+String((ranks.length?Math.max(...ranks):0)+1).padStart(2,'0');}
