function chiffrageHTML(a,C,canEdit,ctx){const ch=a.chiffrage||{};const zones=ch.zones||[];const base=Object.assign({},v1Base(),ch.base||{});const zi=Math.min(AS.zone,Math.max(0,zones.length-1));const z=zones[zi];const Z=C.v2?null:C.zones[zi];const ro=!canEdit;const sites=(ctx&&ctx.sites)||[];const linked=(a.sites||[]).filter(id=>sites.some(s=>s.id===id));
  const versions=ctx&&ctx.vview?'':vBarHTML(a,canEdit,ctx); /* 14/10 après-midi (lot D) : ＋ Nouvelle version (sans limite), écart avec la version précédente, historique consultable (versions.js) — en consultation, le bandeau du haut le remplace */
  const notes0=notesBubbleHTML(a,canEdit); /* 13/10 nuit : une bulle (le nombre à prendre en compte) et un panneau sur le côté — plus la longue liste au-dessus des tableaux */
  if(prixBase())return chiffrage2HTML(a,canEdit,ctx,versions+notes0); /* 13/10 : chiffrage v2 dès que la base de prix est importée */
  const importCard=canEdit?`<div class="card soft"><b>Chiffrage complet (zones, paniers, base de prix SCR)</b><div class="eq-s" style="margin:4px 0 6px">Importe une fois le classeur « Tableau chiffrage vierge » (.xlsm) : taux, cadences, fournitures, paramètres et paniers deviennent la base de prix de l'entreprise (serveur), éditable ici et jamais embarquée dans l'application. Le tableau V2B ci-dessous reste utilisable en attendant.</div><label class="btn primary">📎 Importer le classeur de chiffrage (.xlsm)<input type="file" accept=".xlsm,.xlsx" data-afprix="1" style="display:none"></label></div>`:'';
  const dnRow=(r,i)=>{const R=Z&&Z.rows.find(x=>x.dn===+r.dn);return `<tr><td><select class="f af-dn" data-afz="${i}|dn" ${ro?'disabled':''}>${DNS.map(d=>`<option value="${d}"${+r.dn===d?' selected':''}>DN ${d}</option>`).join('')}</select></td><td><input class="f af-n" type="number" min="0" data-afz="${i}|nb" value="${esc(r.nb||'')}" ${ro?'disabled':''}></td><td><input class="f af-n" type="number" min="0" data-afz="${i}|ml" value="${esc(r.ml||'')}" ${ro?'disabled':''}></td><td class="num">${R?nb(R.pouces):''}</td><td class="num"><b>${R?nb(R.soud):''}</b></td><td class="num">${R?nb(R.manch):''}</td><td class="num">${R?nb(R.jS,1):''}</td><td>${canEdit?`<button class="btn sm" data-act="af" data-v="dnrm|${i}" style="color:#9b2c22">✕</button>`:''}</td></tr>`;};
  const notesCh=notesBubbleHTML(a,canEdit); /* 12/10 : notes de lecture du DCE à destination du chiffrage ; 13/10 : cochables, plusieurs destinations */
  const V=a.chiffrages||[];const vnum=a.chiffrageV||1;
  return importCard+v1DemoBanner()+`<div class="card"><h3>Chiffrage <span class="hint">· version ${vnum}${a.chiffrageNote?' · '+esc(a.chiffrageNote):''} · méthode SCR (tableau V2B)</span></h3>
    ${versions}
    ${notesCh}
    <div class="eq-filtres">${zones.map((zz,i)=>`<button class="chip${i===zi?' active':''}" data-act="af" data-v="zone|${i}">${esc(zz.nom||'Zone '+(i+1))}</button>`).join('')}${canEdit?`<button class="chip" data-act="af" data-v="zoneadd|">➕ zone / lot</button>`:''}</div>
    ${z?`<div class="row" style="display:flex;gap:6px;align-items:end;flex-wrap:wrap;margin:4px 0"><div style="flex:1;min-width:140px"><label class="f">Nom de la zone / du lot</label><input class="f" data-afzn="nom" value="${esc(z.nom||'')}" ${ro?'disabled':''}></div>${canEdit?`<button class="btn" data-act="af" data-v="dnadd|">➕ DN</button>${linked.length?`<select class="f" id="afz-site" style="min-width:150px"><option value="">pré-remplir depuis le tracé…</option>${linked.map(id=>{const s=sites.find(x=>x.id===id);return `<option value="${esc(id)}">${esc(s.name||id)}</option>`;}).join('')}</select><button class="btn" data-act="af" data-v="prefill|">Pré-remplir</button>`:'<span class="hint" style="flex-basis:100%">lie un chantier tracé (onglet Chantiers liés) pour pré-remplir soudures et linéaire par DN</span>'}<button class="btn" data-act="af" data-v="zonerm|" style="color:#9b2c22">✕ zone</button>`:''}</div>
      <div style="overflow:auto"><table class="rc af-tab"><tr><th>DN</th><th>Soudures</th><th>ml tranchée</th><th>Pouces</th><th>Soudure €</th><th>Manchons €</th><th>Jours soud.</th><th></th></tr>${(z.rows||[]).map(dnRow).join('')}
        ${Z?`<tr class="tot"><td>Total</td><td class="num">${nb(Z.nb)}</td><td class="num">${nb(Z.ml)}</td><td class="num">${nb(Z.pouces)}</td><td class="num"><b>${nb(Z.soud)}</b></td><td class="num">${nb(Z.manch)}</td><td class="num">${nb(Z.jS,1)}</td><td></td></tr>`:''}</table></div>
      ${Z?`<div class="eq-s" style="margin-top:6px">Autocontrôle ${nb(base.autocontrole*100)} % : <b>${eur(Z.auto)}</b> · Radios ${nb(base.radioPct*100)} % des soudures = ${nb(Z.radios)} clichés, ${Z.radioVacs} vacation${Z.radioVacs>1?'s':''} : <b>${eur(Z.radioEur)}</b> · Déchets ${nb(Z.t,1)} t / ${nb(Z.m3,1)} m³ · ${nb(Z.jM,1)} jours de manchonnage · <b>Achat zone : ${eur(Z.achat)}</b></div>`:''}`:'<div class="eq-s">Ajoute une zone (lot) pour commencer : chaque zone a sa table par DN.</div>'}</div>
    <div class="card"><h3>Chapitres <span class="hint">· prix d'achat (coût) par poste — comme le Récap Prix</span></h3><div style="overflow:auto"><table class="rc af-tab"><tr><th>Poste</th><th>Achat €</th><th>Vente €</th><th>Observations</th><th></th></tr>${(ch.chapitres||[]).map((c,i)=>`<tr><td><select class="f" data-afc="${i}|k" ${ro?'disabled':''}>${CHAPITRES.map(x=>`<option value="${x[0]}"${c.k===x[0]?' selected':''}>${x[1]}</option>`).join('')}</select></td><td><input class="f af-n" type="number" step="0.01" data-afc="${i}|achat" value="${esc(c.achat||'')}" ${ro?'disabled':''}></td><td class="num">${nb((+c.achat||0)/(1-base.marge))}</td><td><input class="f" data-afc="${i}|obs" value="${esc(c.obs||'')}" ${ro?'disabled':''}></td><td>${canEdit?`<button class="btn sm" data-act="af" data-v="chaprm|${i}" style="color:#9b2c22">✕</button>`:''}</td></tr>`).join('')}</table></div>${canEdit?`<div class="eq-acts" style="margin-top:6px"><button class="btn" data-act="af" data-v="chapadd|">➕ Chapitre</button></div>`:''}</div>
    <div class="card"><h3>Récapitulatif</h3><table class="rc"><tr><td>Soudures + manchons + autocontrôle + radios (zones)</td><td class="num">${eur(C.achat-C.chap)}</td></tr><tr><td>Chapitres</td><td class="num">${eur(C.chap)}</td></tr><tr><td><b>Total prix d'achat</b></td><td class="num"><b>${eur(C.achat)}</b></td></tr><tr><td>Marge ${nb(C.marge*100,1)} % (vente = achat / (1 − marge))</td><td class="num">${eur(C.vente-C.achat)}</td></tr><tr><td><b>Prix de vente</b></td><td class="num"><b>${eur(C.vente)}</b></td></tr><tr><td>RCFA ${nb(C.rcfaPct*100,1)} % ${esc(a.client||'')}</td><td class="num">${eur(C.rcfa)}</td></tr><tr class="tot"><td><b>Total offre € HT</b></td><td class="num"><b>${eur(C.total)}</b></td></tr><tr><td>Info : ${nb(C.nb)} soudures · ${nb(C.ml)} ml · ${nb(C.jS,0)} j soudure · ${nb(C.jM,0)} j manchonnage</td><td class="num">${C.ml?nb(C.parMl,2)+' €/ml':''}</td></tr></table>
      <details style="margin-top:8px"><summary class="eq-s" style="cursor:pointer">⚙ Base de prix (taux horaire, équipes, ratios, marge, RCFA)</summary><div class="row af-grid" style="margin-top:6px">${[['taux','Taux horaire total €/h'],['heures','Heures / jour'],['nSoud','Soudeurs / équipe soudure'],['nManch','Personnes / équipe manchon'],['autocontrole','Autocontrôle (0,05 = 5 %)'],['ratioManchons','Manchons / soudures (0,85)'],['marge','Marge (0,08 = 8 %)'],['dechets','Déchets (0,10 = 10 % du poids)'],['radioPct','Radios (0,05 = 5 % des soudures)'],['radioForfait','Forfait vacation radio €']].map(([k,l])=>`<div><label class="f">${l}</label><input class="f" type="number" step="any" data-afb="${k}" value="${esc(base[k])}" ${ro?'disabled':''}></div>`).join('')}<div><label class="f">RCFA (vide = selon le client)</label><input class="f" type="number" step="any" data-afb="rcfa" value="${esc(ch.rcfa===undefined||ch.rcfa===null?'':ch.rcfa)}" ${ro?'disabled':''} placeholder="${rcfaOf(a.client)}"></div></div>
      <div class="hint" style="margin-top:6px">Prix du pouce = (taux × heures × soudeurs) / (cadence journalière × pouces du DN) ; prix du manchon = (taux × heures × manchonneurs) / cadence ; cadences SCR par DN (3 soudeurs, 1 manchonneur) ; Récap : vente = achat / (1 − marge) comme dans le tableau. Approximation radios : clichés = % des soudures × PU par DN (90 / 115 / 125 / 145 €) + vacations de 9 clichés.</div></details>
      <div class="eq-acts" style="margin-top:8px"><button class="btn" data-act="af" data-v="print|">🖨 Fiche de chiffrage</button></div></div>`;}
function factHTML(a,t,canEdit){const y=t.y;const f=a.fact||{};const sits=(a.situations||[]).filter(s=>!s.deleted).sort((x,yy)=>String(x.mois||'')<String(yy.mois||'')?-1:1);const ro=!canEdit;
  const tabs=(a.dce||[]).filter(d=>!d.deleted&&(/^Facturation/.test(d.cat||'')||catOf(d)==='facturation'));
  return `${mutuFactHTML(a)}<div class="card"><h3>Tableau de facturation du chantier <span class="hint">· envoyé au client</span></h3><div class="hint" style="margin:0 0 6px">Le tableau Excel de facturation envoyé au client (DPGF / situations) se dépose ici à chaque envoi : la dernière version fait foi, les précédentes restent. Ce qui a été facturé se renseigne dans les situations mensuelles ci-dessous pour que le suivi soit à jour.</div>
    ${tabs.length?`<table class="rc">${tabs.slice().reverse().map(d=>`<tr><td>${d.url?`<a href="${esc(d.url)}" target="_blank" rel="noopener" style="color:#1c3d6b;font-weight:600">${esc(d.name)}</a>`:'<b>'+esc(d.name)+'</b>'}${d.size?` <span class="dim" style="font-size:11px">· ${mo(d.size)}</span>`:''}</td><td class="dim">${esc(d.by||'')} · ${dFR(d.at)}</td><td>${canEdit?`<button class="btn sm" data-act="af" data-v="dcerm|${esc(d.id)}" style="color:#9b2c22">✕</button>`:''}</td></tr>`).join('')}</table>`:'<div class="eq-s">Aucun tableau déposé.</div>'}
    ${canEdit?`<div class="eq-acts" style="margin-top:6px"><input type="hidden" id="afd-cat" value="Facturation · tableau client"><label class="btn">📎 Déposer le tableau (Excel, PDF)<input type="file" data-affile="${esc(a.num)}" accept=".xlsx,.xls,.pdf,.csv" style="display:none" multiple></label></div>`:''}</div>
    <div class="card"><h3>Facturation ${y} <span class="hint">· situations mensuelles (reporting d'activité)</span></h3>
    <div class="eq-filtres"><button class="chip" data-act="af" data-v="year|${y-1}">‹ ${y-1}</button><button class="chip active">${y}</button><button class="chip" data-act="af" data-v="year|${y+1}">${y+1} ›</button></div>
    <div style="overflow:auto"><table class="rc af-tab"><tr>${MOIS.map(m=>`<th>${m}</th>`).join('')}<th>Année</th></tr><tr>${MOIS.map((m,i)=>`<td><input class="f af-n" type="number" step="0.01" data-aff="${y}-${String(i+1).padStart(2,'0')}" value="${esc(f[y+'-'+String(i+1).padStart(2,'0')]||'')}" ${ro?'disabled':''}></td>`).join('')}<td class="num"><b>${eur(t.annee)}</b></td></tr></table></div>
    <div class="ac-stats" style="margin-top:8px"><div class="ac-stat"><b>${eur(t.avant)}</b><small>facturé avant ${y}</small></div><div class="ac-stat ok"><b>${eur(t.cumul)}</b><small>cumul situations</small></div><div class="ac-stat ${t.restant>1?'warn':''}"><b>${eur(t.restant)}</b><small>restant à facturer</small></div><div class="ac-stat"><b>${a.montant?nb(100*t.cumul/(+a.montant||1)):'—'} %</b><small>avancement facturé</small></div></div></div>
    <div class="card"><h3>Situations et factures <span class="hint">· suivi des situations</span></h3>
      ${sits.length?`<div style="overflow:auto"><table class="rc af-tab"><tr><th>Mois</th><th>N° situation</th><th>N° facture</th><th>Montant € HT</th><th>RG</th><th>Étape</th><th>Envoi</th><th>Commentaire</th><th></th></tr>${sits.map(s=>`<tr><td><input class="f" type="month" data-afs="${s.id}|mois" value="${esc(s.mois||'')}" ${ro?'disabled':''}></td><td><input class="f" data-afs="${s.id}|sit" value="${esc(s.sit||'')}" ${ro?'disabled':''}></td><td><input class="f" data-afs="${s.id}|num" value="${esc(s.num||'')}" placeholder="FAC-000…" ${ro?'disabled':''}></td><td><input class="f af-n" type="number" step="0.01" data-afs="${s.id}|montant" value="${esc(s.montant||'')}" ${ro?'disabled':''}></td><td><input class="f" data-afs="${s.id}|rg" value="${esc(s.rg||'')}" placeholder="5 % / OK" style="width:70px" ${ro?'disabled':''}></td><td><select class="f" data-afs="${s.id}|etape" ${ro?'disabled':''}>${FACT_ETAPES.map(e=>`<option value="${e[0]}"${s.etape===e[0]?' selected':''}>${e[1]}</option>`).join('')}</select></td><td><input class="f" data-afs="${s.id}|envoi" value="${esc(s.envoi||'')}" placeholder="MLB, mail, factor…" ${ro?'disabled':''}></td><td><input class="f" data-afs="${s.id}|com" value="${esc(s.com||'')}" ${ro?'disabled':''}></td><td>${canEdit?`<button class="btn sm" data-act="af" data-v="sitrm|${esc(s.id)}" style="color:#9b2c22">✕</button>`:''}</td></tr>`).join('')}</table></div>`:'<div class="eq-s">Aucune situation saisie.</div>'}
      ${canEdit?`<div class="eq-acts" style="margin-top:6px"><button class="btn primary" data-act="af" data-v="sitadd|">➕ Situation / facture</button></div>`:''}
      <div class="hint" style="margin-top:6px">Étapes du suivi de facturation : envoi de la situation → validation → préparation de la facture → validation → enregistrement Drive → dépôt (ou avoir) → payée. La RG (retenue de garantie, 5 %) se note par situation. Le montant d'une situation déposée alimente le mois correspondant si la case du mois est vide.</div></div>`;}
/* ── fiche de chiffrage imprimable ── */
export function chiffragePrintHTML(a){const C=calcAffaire(a);const base=Object.assign({},v1Base(),(a.chiffrage||{}).base||{});
  const zones=C.zones.map((Z,i)=>`<h2>${esc(Z.nom||'Zone '+(i+1))}</h2><table class="em"><tr><th>DN</th><th>Soudures</th><th>ml</th><th>Pouces</th><th>Soudure</th><th>Manchons</th><th>Autocontrôle</th><th>Jours soud.</th><th>Jours manch.</th></tr>${Z.rows.map(r=>`<tr><td>DN ${r.dn}</td><td>${nb(r.nb)}</td><td>${nb(r.ml)}</td><td>${nb(r.pouces)}</td><td>${nb(r.soud)}</td><td>${nb(r.manch)}</td><td>${nb(r.auto)}</td><td>${nb(r.jS,1)}</td><td>${nb(r.jM,1)}</td></tr>`).join('')}<tr><td><b>Total</b></td><td><b>${nb(Z.nb)}</b></td><td><b>${nb(Z.ml)}</b></td><td>${nb(Z.pouces)}</td><td><b>${nb(Z.soud)}</b></td><td><b>${nb(Z.manch)}</b></td><td>${nb(Z.auto)}</td><td>${nb(Z.jS,1)}</td><td>${nb(Z.jM,1)}</td></tr></table><p>Radios : ${nb(Z.radios)} clichés, ${Z.radioVacs} vacations → ${eur(Z.radioEur)} · Déchets ${nb(Z.t,1)} t / ${nb(Z.m3,1)} m³ · <b>Achat zone ${eur(Z.achat)}</b></p>`).join('');
  const chap=((a.chiffrage||{}).chapitres||[]).map(c=>`<tr><td>${esc((CHAPITRES.find(x=>x[0]===c.k)||[])[1]||c.k)}</td><td>${nb(c.achat)}</td><td>${nb((+c.achat||0)/(1-base.marge))}</td><td>${esc(c.obs||'')}</td></tr>`).join('');
  return A.docHTML({title:'Chiffrage — '+(a.nom||a.num),kicker:'Commerce · fiche de chiffrage · '+esc(a.num),sub:esc(a.client||'')+(a.ville?' · '+esc(a.ville):''),meta:[['Affaire',esc(a.num)],['État',etat(a.etat)[1]],['Total offre HT',eur(C.total)],['€ / ml',C.ml?nb(C.parMl,2):'—']],
    body:zones+`<h2>Chapitres</h2><table class="em"><tr><th>Poste</th><th>Achat €</th><th>Vente €</th><th>Observations</th></tr>${chap||'<tr><td colspan="4">—</td></tr>'}</table><h2>Récapitulatif</h2><table class="em"><tr><td>Total prix d'achat</td><td>${eur(C.achat)}</td></tr><tr><td>Marge ${nb(C.marge*100,1)} %</td><td>${eur(C.vente-C.achat)}</td></tr><tr><td>Prix de vente</td><td>${eur(C.vente)}</td></tr><tr><td>RCFA ${nb(C.rcfaPct*100,1)} %</td><td>${eur(C.rcfa)}</td></tr><tr><td><b>Total offre € HT</b></td><td><b>${eur(C.total)}</b></td></tr></table>${v1Demo()?'<div class="card soft"><b>Valeurs de démonstration (fictives) — pack SCR non importé.</b></div>':''}<div class="card soft">Base : taux ${nb(base.taux,2)} €/h · ${base.heures} h/j · ${base.nSoud} soudeurs · ${base.nManch} manchonneur · autocontrôle ${nb(base.autocontrole*100)} % · manchons ${nb(base.ratioManchons*100)} % des soudures · déchets ${nb(base.dechets*100)} %.</div>`,css:'table.em td{text-align:right}table.em td:first-child{text-align:left}',footLeft:'SCR · commerce'});}
/* ── actions (data-act="af" data-v="k|arg") ── */
export const DEST={chiffrage:'→ chiffrage',memoire:'→ mémoire technique',risque:'⚠ risque / point de vigilance',question:'? question MOE',info:'ℹ info'};
const mo=b=>b>=1048576?(b/1048576).toFixed(1).replace('.',',')+' Mo':Math.max(1,Math.round(b/1024))+' Ko';
/* 12/10 : dépôt de fichiers du DCE (zip d'origine gardé tel quel, PDF…) → stockage serveur ; hors connexion ou trop gros → la pièce est créée sans fichier, à relier */
export async function affFiles(num,files,ctx,o){return dceFiles(num,files,ctx,{open:!!(o&&o.open),catKey:(()=>{const c=(document.getElementById('afd-cat')||{}).value||'';return /Facturation/.test(c)?'facturation':undefined;})()});} /* o.open : la pièce jointe depuis la Lecture s'y ouvre */ /* 13/10 : zip déballé, pièces classées, gardées sur l'appareil + serveur (dce.js) */
async function affFilesOld(num,files,ctx){const a=affGet(num);if(!a||!ctx.canEdit)return;const L=[...files];let n=0;for(const f of L){const isZip=/\.(zip|7z|rar)$/i.test(f.name);let url=null;
    if(f.size>50*1048576){A.toast(f.name+' : plus de 50 Mo — dépose-le sur le Drive et colle le lien');continue;}
    try{url=A.sync&&A.sync.uploadDoc?await A.sync.uploadDoc('aff_'+String(num).replace(/[^A-Za-z0-9_-]/g,'_'),'dce',f.name,f):null;}catch(e){url=null;}
    const cat=isZip?'DCE · archive d\'origine':/dpgf|bpu/i.test(f.name)?'DCE · DPGF / BPU':/cctp|rc\b|reglement/i.test(f.name)?'DCE · CCTP / règlement':/plan|dwg|dxf/i.test(f.name)?'DCE · plans':(document.getElementById('afd-cat')||{}).value||'Autre';
    const d={id:'D'+Date.now().toString(36)+Math.random().toString(36).slice(2,4),cat,name:f.name,url:url||undefined,size:f.size,type:f.type||'',archive:isZip||undefined,note:url?'':'fichier non envoyé (hors connexion ?) — redépose-le ou colle un lien',by:A.userName(),at:new Date().toISOString()};
    const cur=affGet(num);regSet('affaire',num,{dce:(cur.dce||[]).concat([d])});n++;}
  if(n)A.toast(n+' pièce'+(n>1?'s':'')+' ajoutée'+(n>1?'s':'')+' au DCE');if(ctx.render)ctx.render();}
function dceNoteModal(a,d,ctx){A.openModal(`<h3 style="margin-top:0">Note de lecture <span class="hint">· ${esc(d.name)}</span></h3><div class="hint" style="margin:0 0 6px">Ce que tu surlignerais au stabilo : où (page, article), l'extrait, et pour qui — chiffrage, mémoire technique, risque, question au MOE : une note peut aller à plusieurs endroits. La note garde sa source.</div>
    <div class="row" style="display:flex;gap:6px;flex-wrap:wrap"><div style="flex:1;min-width:120px"><label class="f">Page / article</label><input class="f" id="dn-ref" placeholder="p. 12 · art. 3.4"></div></div><label class="f">Pour qui <span class="dim">(une ou plusieurs destinations — ex. « série 2 imposée » : chiffrage ET mémoire technique)</span></label><div class="eq-opts cm-dests">${Object.entries(DEST).map(([k,v])=>`<label class="chip cm-dest"><input type="checkbox" name="dn-dest" value="${k}"${k==='chiffrage'?' checked':''}> ${v}</label>`).join('')}</div>
    <label class="f">Extrait (copié du document)</label><textarea class="f" id="dn-extrait" style="min-height:56px" placeholder="« Les soudures seront contrôlées à 100 % par ressuage… »"></textarea>
    <label class="f">Ta note</label><input class="f" id="dn-texte" placeholder="ex. prévoir contrôle externe dans le chiffrage, ligne CND">
    <div class="actions" style="margin-top:8px"><button class="btn primary block" id="dn-ok">Ajouter la note</button><button class="btn block" data-close>Annuler</button></div>`);
  document.getElementById('dn-ok').onclick=()=>{const g=id=>(document.getElementById(id)||{}).value||'';const dests=[...document.querySelectorAll('#modal input[name=dn-dest]:checked')].map(x=>x.value);if(!dests.length){A.toast('Coche au moins une destination');return;}const n={ref:g('dn-ref').trim(),dest:dests[0],dests,extrait:g('dn-extrait').trim(),texte:g('dn-texte').trim(),by:A.userName(),at:new Date().toISOString()};if(!n.extrait&&!n.texte){A.toast('Un extrait ou une note');return;}
    const cur=affGet(a.num);regSet('affaire',a.num,{dce:(cur.dce||[]).map(x=>x.id===d.id?Object.assign({},x,{notes:(x.notes||[]).concat([n])}):x)});A.closeModal();A.toast('Note ajoutée · '+dests.map(x=>DEST[x]||x).join(' · '));if(ctx.render)ctx.render();};}
export function affAct(v,el,ctx){const [k,arg,arg2,arg3]=String(v).split('|');const a=AS.cur?affGet(AS.cur):null;const canEdit=ctx.canEdit;const say=t=>A.toast&&A.toast(t);
  if(a&&/^mu/.test(k)&&mutuAct(k,arg,arg2,a,ctx))return; /* 16/10 soir (lot MU) : ajouter au chantier en cours, annuler le rattachement (mutu.js) */
  if(!a&&AS.seg==='prix'&&baseAct(k,arg,arg2,arg3,Object.assign({},ctx,{page:true})))return; /* 13/10 : page Base de prix SCR */
  if(a&&(k==='vnew'||k==='vrestore')&&lzBusy(a))return; /* 14/10 soir (lot L) : pas de version figée pendant qu'un tracé lié arrive du serveur (elle garderait « rien de tracé ») */
  if(a&&vAct(k,arg,arg2,ctx))return; /* 14/10 après-midi (lot D) : versions — nouvelle, consulter, repartir de, retirer, écrits officiels (versions.js) */
  if(['open','back','seg','recap'].includes(k))AS.vview=null; /* changer d'affaire ou de liste : fin de la consultation */
  if(a&&VTABS.includes(AS.tab)&&!['tab','back','open','seg','etat','sect','year','zone','recap'].includes(k)&&vConsulting(a)){ /* 14/10 après-midi (lot D) : CONSULTATION d'une version figée — les actions d'affichage marchent sur l'affaire virtuelle, toute écriture est refusée */
    const va=vVirtual(a,AS.vview);const ro=Object.assign({},ctx,{canEdit:false,canPrix:false});let done=false;
    affWithVirtual(va,()=>{done=dceAct(k,arg,arg2,arg3,ro)||qsetsAct(k,arg,arg2,ro)||commerceAct(k,arg,arg2,arg3,ro)||chiffrageAct(k,arg,arg2,arg3,ro);
      if(!done&&k==='print'){const w=window.open('','_blank');if(!w){say('Autorise la fenêtre pop-up pour imprimer');}else{w.document.write(prixBase()&&etudesOf(va).length?chiffragePrint2HTML(va):chiffragePrintHTML(va));w.document.close();}done=true;}});
    if(!done)say('Lecture seule : tu consultes la v'+AS.vview+' — « Revenir à la version en cours » pour modifier');return;}
  if(a&&dceAct(k,arg,arg2,arg3,ctx))return; /* 13/10 : dossier et lecture (dce.js) */
  if(a&&qsetsAct(k,arg,arg2,ctx))return; /* 13/10 (lot 3) : études fournisseur, saisie, tracé (qsets.js) */
  if(a&&commerceAct(k,arg,arg2,arg3,ctx))return; /* 13/10 : dossier de A à Z (commerce.js) — lecture, mémoire, DPGF, offre */
  if(a&&chiffrageAct(k,arg,arg2,arg3,ctx))return; /* 13/10 : chiffrage v2 (chiffrage.js) */
  const upd=patch=>{if(!a)return;affSet(a.num,patch);};
  switch(k){
    case 'seg':AS.seg=arg;AS.etat='';AS.view=arg==='rep'?'recap':'list';AS.cur=null;break;
    /* vnew · vrestore (« ⇢ Repartir de cette version ») · vrm : versions.js (14/10 après-midi, lot D — instantanés complets, sans limite ; vrestore crée une nouvelle version, n'écrase rien) */
    case 'etat':AS.etat=arg;break;case 'sect':AS.secteur=arg;break;case 'year':AS.year=+arg;break;case 'tab':AS.tab=arg;break;case 'zone':AS.zone=+arg;break;
    case 'open':AS.cur=arg;AS.view='fiche';AS.tab='fiche';AS.zone=0;break;
    case 'back':AS.view='list';AS.cur=null;break;case 'recap':AS.seg='rep';AS.view='list';break;
    case 'csv':{const csv=affCSV();const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const u=URL.createObjectURL(blob);const el2=document.createElement('a');el2.href=u;el2.download='affaires_'+AS.year+'.csv';document.body.appendChild(el2);el2.click();el2.remove();setTimeout(()=>URL.revokeObjectURL(u),2000);return;}
    case 'new':if(!canEdit)return;AS.newOpen=!AS.newOpen;break;
    case 'create':{if(!canEdit)return;const g=id=>(document.getElementById(id)||{}).value||'';const num=g('afn-num').trim().toUpperCase();if(!/^[A-Z]\d{4}-\d{2}/.test(num)){say('Numéro attendu : lettre + AAMM-rang, ex. O2610-01');return;}if(affGet(num)){say('Ce numéro existe déjà');return;}
      affNew(num,{nom:g('afn-nom').trim(),client:g('afn-client').trim(),cp:g('afn-cp').trim(),ville:g('afn-ville').trim(),secteur:g('afn-sect'),etat:g('afn-etat'),montant:g('afn-montant')?+g('afn-montant'):null,dateOuverture:new Date().toISOString().slice(0,10)});AS.newOpen=false;AS.cur=num;AS.view='fiche';AS.tab='fiche';say('Affaire '+num+' créée');break;}
    case 'sub':{if(!canEdit||!a)return;const suf=prompt('Suffixe de la sous-affaire (TS1, BDC1, AV1, OS4…)','TS1');if(!suf)return;const num=a.num+'-'+suf.trim().toUpperCase().replace(/[^A-Z0-9]/g,'');if(affGet(num)){say('Existe déjà');return;}affNew(num,{nom:(a.nom||'')+' : '+suf,client:a.client,cp:a.cp,ville:a.ville,secteur:a.secteur,charge:a.charge,cdtx:a.cdtx,etat:'devis'});AS.cur=num;break;}
    case 'del':{if(!canEdit||!a)return;if(!confirm('Supprimer l\'affaire '+a.num+' ?'))return;regSet('affaire',a.num,{deleted:true,deletedAt:new Date().toISOString()});AS.view='list';AS.cur=null;break;}
    case 'dceadd':{if(!canEdit||!a)return;const g=id=>(document.getElementById(id)||{}).value||'';const name=g('afd-name').trim();if(!name){say('Le nom de la pièce');return;}const cv=g('afd-cat');const d={id:'D'+Date.now().toString(36),catKey:CATS.some(c=>c[0]===cv)?cv:undefined,cat:CATS.some(c=>c[0]===cv)?undefined:(cv||undefined),name,url:g('afd-url').trim()||undefined,note:g('afd-note').trim(),by:A.userName(),at:new Date().toISOString()};upd({dce:(a.dce||[]).concat([d])});break;}
    case 'dcerm':{if(!canEdit||!a)return;upd({dce:(a.dce||[]).filter(d=>d.id!==arg)});break;}
    case 'dcenote':{if(!canEdit||!a)return;const d=(a.dce||[]).find(x=>x.id===arg);if(d)dceNoteModal(a,d,ctx);return;}
    case 'dcenoterm':{if(!canEdit||!a)return;upd({dce:(a.dce||[]).map(x=>x.id===arg?Object.assign({},x,{notes:(x.notes||[]).filter((n,i)=>i!==+arg2)}):x)});break;}
    case 'zoneadd':{if(!canEdit||!a)return;const ch=Object.assign({zones:[],chapitres:[]},a.chiffrage||{});ch.zones=(ch.zones||[]).concat([{nom:'Zone '+((ch.zones||[]).length+1),rows:[{dn:100,nb:'',ml:''}]}]);upd({chiffrage:ch});AS.zone=ch.zones.length-1;break;}
    case 'zonerm':{if(!canEdit||!a)return;const ch=Object.assign({},a.chiffrage||{});if(!confirm('Retirer cette zone du chiffrage ?'))return;ch.zones=(ch.zones||[]).filter((z,i)=>i!==AS.zone);upd({chiffrage:ch});AS.zone=0;break;}
    case 'dnadd':{if(!canEdit||!a)return;const ch=Object.assign({},a.chiffrage||{});const z=(ch.zones||[])[AS.zone];if(!z)return;z.rows=(z.rows||[]).concat([{dn:DNS.find(d=>!(z.rows||[]).some(r=>+r.dn===d))||100,nb:'',ml:''}]);upd({chiffrage:ch});break;}
    case 'dnrm':{if(!canEdit||!a)return;const ch=Object.assign({},a.chiffrage||{});const z=(ch.zones||[])[AS.zone];if(!z)return;z.rows=(z.rows||[]).filter((r,i)=>i!==+arg);upd({chiffrage:ch});break;}
    case 'prefill':{if(!canEdit||!a)return;const sel=document.getElementById('afz-site');const id=sel&&sel.value;if(!id){say('Choisis le chantier tracé');return;}const agg=ctx.traceAgg?ctx.traceAgg(id):null;if(!agg||!Object.keys(agg).length){say('Rien à lire dans ce tracé sur cet appareil (ouvre-le une fois)');return;}
      const ch=Object.assign({},a.chiffrage||{});const z=(ch.zones||[])[AS.zone];if(!z)return;z.rows=Object.keys(agg).map(Number).sort((x,y)=>x-y).map(dn=>({dn,nb:agg[dn].nb,ml:Math.round(agg[dn].ml)}));z.source=id;upd({chiffrage:ch});say('Zone pré-remplie depuis le tracé : '+z.rows.length+' DN');break;}
    case 'chapadd':{if(!canEdit||!a)return;const ch=Object.assign({zones:[],chapitres:[]},a.chiffrage||{});ch.chapitres=(ch.chapitres||[]).concat([{k:'conteneur',achat:'',obs:''}]);upd({chiffrage:ch});break;}
    case 'chaprm':{if(!canEdit||!a)return;const ch=Object.assign({},a.chiffrage||{});ch.chapitres=(ch.chapitres||[]).filter((c,i)=>i!==+arg);upd({chiffrage:ch});break;}
    case 'sitadd':{if(!canEdit||!a)return;const now=new Date();upd({situations:(a.situations||[]).concat([{id:'S'+Date.now().toString(36),mois:now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0'),etape:'envoi',montant:'',sit:String((a.situations||[]).length+1)}])});break;}
    case 'sitrm':{if(!canEdit||!a)return;upd({situations:(a.situations||[]).filter(s=>s.id!==arg)});break;}
    case 'link':{if(!canEdit||!a)return;const sel=document.getElementById('afs-site');const id=sel&&sel.value;if(!id||(a.sites||[]).includes(id))return;const off=Object.assign({},a.sitesOff||{});delete off[id];upd(Object.assign({sites:(a.sites||[]).concat([id])},a.sitesOff&&a.sitesOff[id]?{sitesOff:off}:{}));lzLinkSite(a.num,id);break;} /* 14/10 soir (lot L) : lié à la main = il reste lié (et un chantier réel garde « Ouvrir ») */
    case 'unlink':{if(!canEdit||!a)return;upd({sites:(a.sites||[]).filter(x=>x!==arg),sitesOff:Object.assign({},a.sitesOff||{},{[arg]:new Date().toISOString()})});lzUnlinkSite(a.num,arg);break;} /* 14/10 soir (lot L) : ✕ qui tient — a.sitesOff (partagé, tous les appareils) + repère du chantier marqué délié */
    case 'etopen':{if(!a||!arg)return;lzOpenEtude(arg,a.num);return;}
    case 'etrecount':{if(!a||!arg)return;lzRecountEtude(arg,a.num);return;} /* 28/10 (lot 2810e) : ⟳ Recompter (moteur du jour) */
    case 'etviewer':case 'etmail':case 'etlink':{if(!a||!arg)return;if(ctx.traceViewer)ctx.traceViewer(arg,{zip:k==='etmail',link:k==='etlink'});else say('Export indisponible ici');return;} /* 28/10 (lot 2810d) : etlink = le lien à envoyer */ /* 28/10 (lot 2810b) : etmail = la même maquette zippée, pour un mail */ /* 27/10 soir (lot 2710j) : Plan interactif (.html) d'une étude, sans ouvrir l'écran Tracé */ /* 14/10 soir (lot L) : une étude s'ouvre dans le traceur de l'affaire (C6 : site, aff, cv) */
    case 'print':{if(!a)return;const w=window.open('','_blank');if(!w){say('Autorise la fenêtre pop-up pour imprimer');return;}w.document.write(prixBase()&&etudesOf(a).length?chiffragePrint2HTML(a):chiffragePrintHTML(a));w.document.close();return;}
    default:return;}
  if(ctx.render)ctx.render();}
/* ── saisie des champs (data-afin, data-afz, data-afc, data-afb, data-aff, data-afs, data-afzn) ── */
export function affInput(el,ctx){const d=el.dataset;if(d.afin==='q'){AS.q=el.value;if(ctx.render)ctx.render();return true;}if(d.afin==='newsect'){const n=document.getElementById('afn-num');if(n)n.value=affNextNum(el.value);return true;}
  if(AS.cur&&VTABS.includes(AS.tab)){const a0=affGet(AS.cur);if(a0&&vConsulting(a0)){const va=vVirtual(a0,AS.vview);const ro=Object.assign({},ctx,{canEdit:false,canPrix:false});let done=false; /* 14/10 après-midi (lot D) : consultation — champs d'affichage seulement */
    affWithVirtual(va,()=>{done=qsetsInput(el,ro)||dceInput(el,ro)||chiffrageInput(el,ro);});if(!done&&A.toast)A.toast('Lecture seule : tu consultes la v'+AS.vview+' — « Revenir à la version en cours » pour modifier');return true;}}
  if(qsetsInput(el,ctx))return true; /* 13/10 (lot 3) : nom d'une étude, lignes saisies à la main */
  if(dceInput(el,ctx))return true; /* 13/10 : pièces (catégorie, nouvelle version) */
  if(chiffrageInput(el,ctx))return true; /* 13/10 : chiffrage v2 (data-afx, import du classeur data-afprix) */
  if(!ctx.canEdit){if(A.toast)A.toast('Lecture seule : droit « Affaires : créer et modifier » nécessaire');return true;}
  const a=AS.cur?affGet(AS.cur):null;if(!a)return false;const num=v=>v===''?null:(isFinite(+v)?+v:v);
  if(d.afin){affSet(a.num,{[d.afin]:['montant','cumulN1'].includes(d.afin)?num(el.value):el.value});if(d.afin==='etat'&&ctx.render)ctx.render(); /* l'état change les onglets (Facturation) et l'étiquette */return true;}
  if(commerceInput(el,ctx))return true; /* 13/10 : consultation (afcs), quantités (afq / afqr), mémoire (afm), DPGF (afdp) */
  if(d.afzn){const ch=Object.assign({},a.chiffrage||{});const z=(ch.zones||[])[AS.zone];if(z){z.nom=el.value;affSet(a.num,{chiffrage:ch});}return true;}
  if(d.afz){const [i,k]=d.afz.split('|');const ch=Object.assign({},a.chiffrage||{});const z=(ch.zones||[])[AS.zone];if(z&&z.rows[+i]){z.rows[+i][k]=k==='dn'?+el.value:num(el.value);affSet(a.num,{chiffrage:ch});}if(ctx.render)ctx.render();return true;}
  if(d.afc){const [i,k]=d.afc.split('|');const ch=Object.assign({},a.chiffrage||{});const c=(ch.chapitres||[])[+i];if(c){c[k]=k==='achat'?num(el.value):el.value;affSet(a.num,{chiffrage:ch});}if(ctx.render)ctx.render();return true;}
  if(d.afb){const ch=Object.assign({},a.chiffrage||{});if(d.afb==='rcfa'){ch.rcfa=el.value===''?null:+el.value;}else{ch.base=Object.assign({},ch.base||{});ch.base[d.afb]=+el.value;}affSet(a.num,{chiffrage:ch});if(ctx.render)ctx.render();return true;}
  if(d.aff){const f=Object.assign({},a.fact||{});if(el.value==='')delete f[d.aff];else f[d.aff]=+el.value;affSet(a.num,{fact:f});if(ctx.render)ctx.render();return true;}
  if(d.afs){const [id,k]=d.afs.split('|');const sits=(a.situations||[]).map(s=>s.id===id?Object.assign({},s,{[k]:k==='montant'?num(el.value):el.value}):s);const patch={situations:sits};const s=sits.find(x=>x.id===id);
    if(s&&(k==='etape'||k==='montant')&&s.etape==='depot'&&s.mois&&s.montant){const f=Object.assign({},a.fact||{});if(f[s.mois]===undefined||f[s.mois]===''||f[s.mois]===null){f[s.mois]=+s.montant;patch.fact=f;}} /* facture déposée → alimente le mois si vide */
    affSet(a.num,patch);if(ctx.render)ctx.render();return true;}
  return false;}
export function affRecapHTML(){const y=AS.year;const all=affAll();const sects=Object.keys(SECTEURS_AFF).filter(k=>all.some(a=>(a.secteur||SECT_LETTER[String(a.num)[0]])===k));const M=MOIS.map((m,i)=>y+'-'+String(i+1).padStart(2,'0'));
  const cell=(k,mo)=>all.filter(a=>(a.secteur||SECT_LETTER[String(a.num)[0]])===k).reduce((s,a)=>s+(+(a.fact||{})[mo]||0),0);const totS={};sects.forEach(k=>totS[k]=M.reduce((s,mo)=>s+cell(k,mo),0));const tot=M.map(mo=>sects.reduce((s,k)=>s+cell(k,mo),0));const T=tot.reduce((s,x)=>s+x,0);
  const restant={};sects.forEach(k=>restant[k]=all.filter(a=>(a.secteur||SECT_LETTER[String(a.num)[0]])===k&&['en_cours','a_debuter'].includes(a.etat)).reduce((s,a)=>s+Math.max(0,factTotaux(a,y).restant),0));const devis={};sects.forEach(k=>devis[k]=all.filter(a=>(a.secteur||SECT_LETTER[String(a.num)[0]])===k&&['devis','preconsult'].includes(a.etat)).reduce((s,a)=>s+(+a.montant||0),0));
  return `<div class="card"><h3>CA mensuel ${y} par secteur <span class="hint">· situations facturées (reporting)</span></h3><div class="eq-filtres"><button class="chip" data-act="af" data-v="year|${y-1}">‹ ${y-1}</button><button class="chip active">${y}</button><button class="chip" data-act="af" data-v="year|${y+1}">${y+1} ›</button></div>
    <div style="overflow:auto"><table class="rc af-tab"><tr><th>Mois</th>${sects.map(k=>`<th>${esc(SECTEURS_AFF[k])}</th>`).join('')}<th>Total SCR</th></tr>${M.map((mo,i)=>`<tr><td>${MOIS[i]}</td>${sects.map(k=>`<td class="num">${cell(k,mo)?nb(cell(k,mo)/1000)+' k€':'—'}</td>`).join('')}<td class="num"><b>${tot[i]?nb(tot[i]/1000)+' k€':'—'}</b></td></tr>`).join('')}<tr class="tot"><td>Total ${y}</td>${sects.map(k=>`<td class="num">${nb(totS[k]/1000)} k€</td>`).join('')}<td class="num">${nb(T/1000)} k€</td></tr><tr><td>Part</td>${sects.map(k=>`<td class="num">${T?nb(100*totS[k]/T):0} %</td>`).join('')}<td></td></tr><tr><td>Restant à facturer</td>${sects.map(k=>`<td class="num">${nb(restant[k]/1000)} k€</td>`).join('')}<td class="num"><b>${nb(Object.values(restant).reduce((s,x)=>s+x,0)/1000)} k€</b></td></tr><tr><td>Devis / préconsult. en cours</td>${sects.map(k=>`<td class="num">${nb(devis[k]/1000)} k€</td>`).join('')}<td class="num">${nb(Object.values(devis).reduce((s,x)=>s+x,0)/1000)} k€</td></tr></table></div>
    <div class="eq-acts" style="margin-top:8px"><button class="btn" data-act="af" data-v="csv|">⬇ Export CSV des affaires (Excel)</button></div><div class="hint" style="margin-top:4px">Même logique que l'onglet Récap du reporting : CA = situations mensuelles saisies sur chaque affaire.</div></div>`;}
export function affCSV(){const all=affAll();const y=AS.year;const H=['Numéro','Nom','État','Secteur','Client','CP','Ville','Chargé d\'affaires','CDTX','Montant devis HT','Cumul N-1','Cumul situations','Restant à facturer'].concat(MOIS.map(m=>m+' '+y)).concat(['Commentaires']);
  const E=ETATS.reduce((o,e)=>{o[e[0]]=e[1];return o;},{});const q=v=>'"'+String(v===undefined||v===null?'':v).replace(/"/g,'""')+'"';
  const rows=all.map(a=>{const t=factTotaux(a,y);return [a.num,a.nom,E[a.etat]||a.etat,SECTEURS_AFF[a.secteur||SECT_LETTER[String(a.num)[0]]]||'',a.client,a.cp,a.ville,a.charge,a.cdtx,a.montant,a.cumulN1,t.cumul,t.restant].concat(t.mois).concat([a.commentaire]).map(v=>typeof v==='number'?String(v).replace('.',','):q(v)).join(';');});
  return '\ufeff'+H.map(q).join(';')+'\n'+rows.join('\n');}
export function affView(me,ctx){const canEdit=ctx.canEdit;const segBar=`<div class="eq-filtres af-segs">${SEGS.map(([k,l])=>`<button class="chip${AS.seg===k?' active':''}" data-act="af" data-v="seg|${k}">${l}</button>`).join('')}</div>`;
  if(AS.view==='fiche'&&AS.cur)return `<button class="ac-back" data-act="af" data-v="back|">‹ ${esc((SEGS.find(x=>x[0]===AS.seg)||SEGS[1])[1].replace(/^\S+\s/,''))}</button>`+affFicheHTML(me,canEdit,ctx);
  if(AS.seg==='rep')return `<h2 class="vt">Commerce <span class="hint">· reporting : toutes les affaires, le gagné, le facturé, le restant</span></h2>`+segBar+affRecapHTML()+dbOverviewHTML(ctx)+affTraceHTML(); /* 19/10 (lot DB) : débours des affaires en cours */
  if(AS.seg==='prix')return `<h2 class="vt">Commerce <span class="hint">· base de prix SCR</span></h2>`+segBar+prixPageHTML(ctx);
  const sg=SEGS.find(x=>x[0]===AS.seg)||SEGS[1];
  return `<h2 class="vt">Commerce <span class="hint">· ${esc(sg[1].replace(/^\S+\s/,''))}</span></h2>`+segBar+`<div class="hint" style="margin:0 0 6px">${AS.seg==='devis'?'En suspens, ni gagné ni perdu : préconsultations et devis — création de l\'affaire, DCE, chiffrage (versions : négociation, alignement technique — chacune figée et consultable), offre remise.':AS.seg==='cours'?'Affaires gagnées : à débuter et en cours — chantiers liés, tableau de facturation envoyé au client, situations renseignées pour un suivi à jour.':'Dossiers terminés et perdus : la traçabilité reste (chiffrage, facturé, documents).'}</div>`+affListHTML(me,canEdit);}
/* traçabilité : toutes les affaires créées, une ligne chacune */
function affTraceHTML(){const y=AS.year;const all=affAll().slice().sort((a,b)=>String(a.num).localeCompare(String(b.num)));const E=Object.fromEntries(ETATS.map(e=>[e[0],e[1]]));
  const won=all.filter(a=>['a_debuter','en_cours','termine'].includes(a.etat)),lost=all.filter(a=>a.etat==='perdu'),pend=all.filter(a=>['preconsult','devis'].includes(a.etat));
  const sum=L=>L.reduce((s,a)=>s+(+a.montant||0),0);const fact=all.reduce((s,a)=>s+factTotaux(a,y).cumul,0);const rest=won.reduce((s,a)=>s+Math.max(0,factTotaux(a,y).restant),0);
  return `<div class="ac-stats" style="margin:8px 0"><div class="ac-stat"><b>${all.length}</b><small>affaires créées</small></div><div class="ac-stat ok"><b>${won.length} · ${nb(sum(won)/1000)} k€</b><small>gagnées</small></div><div class="ac-stat"><b>${pend.length} · ${nb(sum(pend)/1000)} k€</b><small>en suspens (devis)</small></div><div class="ac-stat bad"><b>${lost.length} · ${nb(sum(lost)/1000)} k€</b><small>perdues</small></div><div class="ac-stat"><b>${nb(fact/1000)} k€</b><small>facturé cumulé</small></div><div class="ac-stat ${rest>0?'warn':''}"><b>${nb(rest/1000)} k€</b><small>restant à facturer</small></div></div>
    <div class="card"><h3>Traçabilité <span class="hint">· ${all.length} affaires</span></h3><div style="overflow:auto"><table class="rc af-tab"><tr><th>N°</th><th>Affaire</th><th>Client</th><th>État</th><th>Chargé</th><th>Montant</th><th>Facturé</th><th>Restant</th><th>Chiffrage</th></tr>${all.map(a=>{const t=factTotaux(a,y);return `<tr><td><button class="lnk" data-act="af" data-v="open|${esc(a.num)}">${esc(a.num)}</button></td><td>${esc(a.nom||'')}</td><td>${esc(a.client||'')}</td><td>${tag(a.etat)}</td><td>${esc(a.charge||'')}</td><td class="num">${a.montant?eur(a.montant):'—'}</td><td class="num">${t.cumul?eur(t.cumul):'—'}</td><td class="num">${a.montant&&['a_debuter','en_cours','termine'].includes(a.etat)?eur(Math.max(0,t.restant)):'—'}</td><td class="num">v${a.chiffrageV||1}${(a.chiffrages||[]).length?' <span class="dim">('+(a.chiffrages||[]).length+' gardées)</span>':''}</td></tr>`;}).join('')}</table></div></div>`;}
export const affReady=()=>regLoaded('affaire');
